#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

typedef struct {
    int to;
    int nxt;
} Edge;

int head[MAXN], edge_cnt;
Edge edges[2 * MAXN];

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].nxt = head[u];
    head[u] = edge_cnt++;

    edges[edge_cnt].to = u;
    edges[edge_cnt].nxt = head[v];
    head[v] = edge_cnt++;
}

int dist[MAXN];
int parent_node[MAXN];
int queue[MAXN];

void bfs(int start, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        parent_node[i] = 0;
    }
    int front = 0, rear = 0;
    dist[start] = 0;
    queue[rear++] = start;

    while (front < rear) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].nxt) {
            int v = edges[e].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent_node[v] = u;
                queue[rear++] = v;
            }
        }
    }
}

long long count_nodes_at_depth(int start, int forbidden, int target_depth, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
    }
    int front = 0, rear = 0;
    dist[start] = 1; // start is at depth 1 from the center
    dist[forbidden] = -2; // mark forbidden as visited/blocked
    queue[rear++] = start;

    long long count = 0;
    while (front < rear) {
        int u = queue[front++];
        if (dist[u] == target_depth) {
            count++;
        }
        for (int e = head[u]; e != -1; e = edges[e].nxt) {
            int v = edges[e].to;
            if (v != forbidden && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
        }
    }
    return count;
}

int path[MAXN];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }
    edge_cnt = 0;

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
    }

    // Step 1: Find one diameter endpoint
    bfs(1, n);
    int nodeA = 1;
    for (int i = 2; i <= n; i++) {
        if (dist[i] > dist[nodeA]) {
            nodeA = i;
        }
    }

    // Step 2: BFS from nodeA to find diameter and full diameter path
    bfs(nodeA, n);
    int nodeB = 1;
    for (int i = 2; i <= n; i++) {
        if (dist[i] > dist[nodeB]) {
            nodeB = i;
        }
    }

    int D = dist[nodeB];
    printf("%d\n", D + 1);

    // Reconstruct path from nodeB to nodeA
    int curr = nodeB;
    int path_len = 0;
    while (curr != 0) {
        path[path_len++] = curr;
        curr = parent_node[curr];
    }
    // Now path[0] = nodeB, path[D] = nodeA
    // Reverse it so that path[0] = nodeA and path[D] = nodeB
    for (int i = 0; i < path_len / 2; i++) {
        int tmp = path[i];
        path[i] = path[path_len - 1 - i];
        path[path_len - 1 - i] = tmp;
    }

    long long ans = 0;

    if (D % 2 == 0) {
        int k = D / 2;
        int center = path[k];

        long long sum = 0;
        long long sum_sq = 0;

        for (int e = head[center]; e != -1; e = edges[e].nxt) {
            int neighbor = edges[e].to;
            long long c = count_nodes_at_depth(neighbor, center, k, n);
            sum += c;
            sum_sq += c * c;
        }

        ans = (sum * sum - sum_sq) / 2;
    } else {
        int k = D / 2;
        int c1 = path[k];
        int c2 = path[k + 1];

        long long count1 = 0;
        // Count in c1's side at distance k from c1
        // Distance from c1 to itself is 0, so nodes at dist k-1 from its neighbors (excluding c2)
        if (k == 0) {
            count1 = 1;
        } else {
            for (int e = head[c1]; e != -1; e = edges[e].nxt) {
                int neighbor = edges[e].to;
                if (neighbor != c2) {
                    count1 += count_nodes_at_depth(neighbor, c1, k, n);
                }
            }
        }

        long long count2 = 0;
        if (k == 0) {
            count2 = 1;
        } else {
            for (int e = head[c2]; e != -1; e = edges[e].nxt) {
                int neighbor = edges[e].to;
                if (neighbor != c1) {
                    count2 += count_nodes_at_depth(neighbor, c2, k, n);
                }
            }
        }

        ans = count1 * count2;
    }

    printf("%lld\n", ans);

    return 0;
}
